import{_t as e,it as t,n,rt as r}from"./chunks/framework.CEeTaPkX.js";var i=JSON.parse(`{"title":"System and request flow","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md","lastUpdated":1792141151000}`),a={name:`architecture/overview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="system-and-request-flow" tabindex="-1">System and request flow <a class="header-anchor" href="#system-and-request-flow" aria-label="Permalink to “System and request flow”">​</a></h1><p>Caret separates routing, conversation execution and Mac I/O. The supervisor chooses the execution surface; the Pi worker handles a bounded foreground task; the native helper performs individual Mac operations.</p><h2 id="system-map" tabindex="-1">System map <a class="header-anchor" href="#system-map" aria-label="Permalink to “System map”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>User / command bar / CLI</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>Agent server :7778 ─────── request lifecycle, SSE, Stop, diagnostics</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>Letta supervisor :4500 ─── persistent persona and memory</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ├── herdr tools ───── coding agents / owned shell workspace</span></span>
<span class="line"><span>           ├── web_* tools ──── cmux browser (background)</span></span>
<span class="line"><span>           └── run_mac_task ─── Pi Durable harness / SQLite</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                               observe / act / finish</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                               Caret.app :7777</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                          Accessibility / GUI / screenshots</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Evidence: turn traces + task state + schema-lite records → local vault</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>This is a responsibility map, not a process count: Pi runs inside the agent server; the native app and Letta server are separate services. Ports shown are defaults.</p><h2 id="follow-one-foreground-task" tabindex="-1">Follow one foreground task <a class="header-anchor" href="#follow-one-foreground-task" aria-label="Permalink to “Follow one foreground task”">​</a></h2><ol><li>The server receives a request and establishes trace/lifecycle state. The supervisor receives the user&#39;s request and chooses a tool.</li><li>Under <code>CARET_CU=v2</code>, <code>run_mac_task</code> arguments are converted to a <code>TaskSpec</code>; the request trace ID is injected. The task needs a complete goal because its Pi conversation starts with only its task card and applicable context.</li><li>The async adapter starts a task and returns its ID. <code>task_status</code> polls progress and eventually a structured result. A tool submission is not a completion claim.</li><li>The runner creates or reuses a Pi conversation and stores <code>caret.task</code>. The model sees the <code>mac-control</code> extension and uses <code>observe</code>, <code>act</code>, and <code>finish</code>.</li><li><code>act</code> validates its action batch, applies guards and executor logic, checks observable predicates, and persists progress. The helper performs the Mac I/O.</li><li><code>finish</code> evaluates declared success checks and settles the task. The runner gathers usage, writes eligible task records, cleans secret state and returns the result.</li></ol><p>The legacy mode instead uses a long-lived root conversation and seven simpler tools. The code selects legacy unless <code>CARET_CU</code> is exactly <code>v2</code>; the documented local setup uses v2. A reader should verify configuration rather than assume all installations use the same mode.</p><h2 id="ownership-and-state" tabindex="-1">Ownership and state <a class="header-anchor" href="#ownership-and-state" aria-label="Permalink to “Ownership and state”">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Owner</th><th>Why it is separate</th></tr></thead><tbody><tr><td>User request lifecycle</td><td>Server</td><td>A request can delegate more than one task</td></tr><tr><td>Supervisor identity and memory</td><td>Letta binding / memfs</td><td>Routes work across requests</td></tr><tr><td>Pi conversation and tool journal</td><td>Pi Durable / SQLite</td><td>Maintains durable execution history</td></tr><tr><td>Task progress and result</td><td>Caret <code>TaskDoc</code></td><td>Provides domain-specific counters, plan and evidence</td></tr><tr><td>Live UI and input policy</td><td>Native helper and executor</td><td>The real Mac can change outside the conversation</td></tr><tr><td>Record blobs and JSONL</td><td>Local vault</td><td>Supports audit and later analysis</td></tr></tbody></table><p>A shared trace is a join key across these layers, not proof that their lifecycles are identical.</p><h2 id="source-trail" tabindex="-1">Source trail <a class="header-anchor" href="#source-trail" aria-label="Permalink to “Source trail”">​</a></h2><p><a href="https://github.com/krishpop/caret/blob/57d53c0/src/server.ts" target="_blank" rel="noreferrer">Server</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/supervisor.ts" target="_blank" rel="noreferrer">Supervisor</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/harness.ts" target="_blank" rel="noreferrer">Harness</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/cu/task.ts" target="_blank" rel="noreferrer">Task runner</a> · <a href="https://github.com/krishpop/caret/tree/57d53c0/mac-helper/Sources/Caret" target="_blank" rel="noreferrer">Native helper</a></p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};